def middle_characters(s):
    if not s:
        return ""
    mid = len(s) // 2
    if len(s) % 2 == 1:
        return s[mid]
    return s[mid-1:mid+1]

def rotate_right(lst, k):
    if not lst:
        return []
    k = k % len(lst)
    if k == 0:
        return lst[:]
    return lst[-k:] + lst[:-k]

def days_remaining_in_year(year, month, day):
    lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
    if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0):
        lengths[1] = 29
    doy = sum(lengths[:month-1]) + day
    return sum(lengths) - doy

def is_valid_query_string(s):
    if not s.startswith('?') or len(s) < 2:
        return False
    body = s[1:]
    pairs = body.split('&')
    for p in pairs:
        if p.count('=') != 1:
            return False
        k, v = p.split('=')
        if not k or not v or not k.isalnum() or not v.isalnum():
            return False
    return True

def score_bucket_counts(scores):
    d = {}
    for s in scores:
        if s >= 100:
            label = "100+"
        else:
            low = (s // 10) * 10
            label = f"{low}-{low + 9}"
        d[label] = d.get(label, 0) + 1
    return d

def keep_every_kth(lst, k):
    if k <= 0:
        return []
    return [x for idx, x in enumerate(lst, start=1) if idx % k == 0]

def words_appearing_at_least(text, k):
    counts = {}
    for w in text.split():
        counts[w] = counts.get(w, 0) + 1
    return sorted(w for w, c in counts.items() if c >= k)

def count_weekends_in_day_range(start_day_num, end_day_num):
