def wrap_and_count(text, width):
    words = text.split()
    lines = []
    current = ''
    for w in words:
        if not current:
            current = w
        elif len(current) + 1 + len(w) <= width:
            current += ' ' + w
        else:
            lines.append(current)
            current = w
    if current:
        lines.append(current)
    return len(lines)

def is_valid_account_mask(s):
    if len(s) < 8 or not s.startswith('****'):
        return False
    if s[4] == '*':
        return False
    digits = s[4:]
    return digits.isdigit() and 4 <= len(digits) <= 12

def to_kebab_case(s):
    import re
    parts = re.split(r'[_ ]+', s.strip('_ '))
    return "-".join(p.lower() for p in parts if p)

def drop_middle_names(name):
    parts = name.split()
    if len(parts) <= 2:
        return name
    return parts[0] + ' ' + parts[-1]

def format_duration_words(total_minutes):
    h = total_minutes // 60
    m = total_minutes % 60
    parts = []
    if h > 0:
        parts.append(f"{h} hour" + ("" if h == 1 else "s"))
    if m > 0 or h == 0:
        parts.append(f"{m} minute" + ("" if m == 1 else "s"))
    return " ".join(parts)

def countdown_seconds(current_seconds, target_seconds):
    if target_seconds == current_seconds:
        return 0
    diff = target_seconds - current_seconds
    if diff < 0:
        diff += 86400
    return diff

