def build_multimap(pairs):
    res = {}
    for k, v in pairs:
        res.setdefault(k, set()).add(v)
    return {k: sorted(vs) for k, vs in res.items()}

def sentence_case_preserve_acronyms(s, acronyms):
    lowered = s.lower()
    for i, ch in enumerate(lowered):
        if ch.isalpha():
            lowered = lowered[:i] + ch.upper() + lowered[i + 1:]
            break
    words = lowered.split(" ")
    acro_map = {a.lower(): a for a in acronyms}
    fixed_words = [acro_map.get(w.lower(), w) for w in words]
    return " ".join(fixed_words)

def max_sum_non_adjacent(lst):
    incl, excl = 0, 0
    for x in lst:
        new_incl = excl + x
        new_excl = max(incl, excl)
        incl, excl = new_incl, new_excl
    return max(incl, excl, 0)

def split_in_half(s):
